import {ACTION_CARDS} from './basic-actions.js';
import {sequenceStep,sequenceCard,sequenceParameters,sequenceRegions,sequenceInfluencePreview,resetChoices,sequenceMarket,sequenceName,sequenceStatus,sequenceStartIssue} from './card-sequence.js';
import {sequenceStepTitle} from './sequence-progress.js';
import {AREAS} from './world.js';
import {RESOURCE_LABELS,ECONOMY} from './economy.js';
import {regionCountries} from './country-piles.js';
import {specialPlayPreview} from './special-cards.js';
import {resilienceControls,readResilience,updateResilience} from './growth-triggers-ui.js';
import {industrializePreview} from './special-effects.js';
import {otherArmyTargets,returnArmyPreview,readyRegionalAllies} from './opponent-effects.js';
import {renderForeignInvestmentStep,readForeignInvestment,updateForeignInvestment} from './foreign-investments-ui.js';
import {renderInspectOpponent,renderCopyAbility,readCopyAbility,updateCopyAbility} from './intelligence-ui.js';
import {renderDDAssetStep,readDDAssetStep,updateDDAssetStep} from './dd-assets-ui.js';
const names={US:'美国',CN:'中国',EU:'欧盟',RU:'俄罗斯'};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles={base:'建立基地',relations:'改善关系',engage:'介入地区',trade:'贸易',invest:'投资盟国',reinforce:'移动军队',domestic:'生产或取得发展牌',choice:'选择牌面行动',move:'移动军队',growth:'取得发展牌',produce:'生产资源',prosperity:'支付2消费品提升繁荣',extra:'打出另一张牌',skip:'不执行可选效果',repeat:'在另一地区再执行一次',extend:'支付2外交，追加永久影响力'};
export function renderSequenceStart(s,id,cards={}){const card=ACTION_CARDS[id],p=s.players[s.current];let cover='';if(card.source){try{specialPlayPreview(s,{cardId:id,cover:p.hand[0]});}catch(error){return `<p>${esc(error.message)}</p>`;}cover=p.hand.length?`<label>盖放一张手牌<select id="sequence-cover">${p.hand.map(cid=>`<option value="${cid}">${esc(cards[cid]?.name||ACTION_CARDS[cid]?.name||'能力牌')}</option>`).join('')}</select></label>`:'<p>手牌为空，无需盖牌。</p>';}
 const issue=sequenceStartIssue(s,id);return `<section class="flow-panel"><b>${esc(card.name)} · 逐段结算</b><p>${card.source?'盖放的手牌本次不执行效果；此牌全局只能使用一次。':'打出后按牌面顺序处理，抽到的手牌可在后续步骤使用。'}每次选择都会保存。</p>${issue?'<p role="status"><b>禁止打出：</b>'+esc(issue)+'。卡牌、费用和使用次数均未消耗。</p>':cover}<button data-card-action="startSequenceCard" data-id="${id}" ${issue?'disabled':''}>打出并开始结算</button></section>`;}
export function renderSequencePanel(s,cards){const q=s.flow?.cardResolution;if(!q)return '';const step=sequenceStep(s),p=s.players[s.current];let body='';
 if(step.type==='effect'){const card=sequenceCard(s);body=`<p>下一步：${titles[card.effect]}${card.domesticMode==='produce'?'（生产）':card.domesticMode==='growth'?'（取得发展牌）':''}。</p><button data-card="${q.copiedCardId||q.cardId}" data-source="resolution">选择目标并结算这一段</button>`;}
 if(step.type==='inspectOpponent')body=renderInspectOpponent(s);
 if(['aidAllies','swapInfluence','beijingConsensus','regimeChange'].includes(step.type))body=renderDDAssetStep(s,sequenceParameters(s),cards);
 if(step.type==='copyAbility')body=renderCopyAbility(s,sequenceParameters(s),cards);
 if(step.type==='chooseActions')body=`<p>选择${step.count}项不同效果，按以下顺序执行。${esc(step.note||'')}</p>${Array.from({length:step.count},(_,i)=>`<label>第${i+1}项<select data-sequence-choice="${i}">${Object.keys(step.options).map((key,j)=>`<option value="${key}" ${j===i?'selected':''}>${titles[key]||key}</option>`).join('')}</select></label>`).join('')}<button id="sequence-resolve">按此顺序继续</button>`;
 if(step.type==='exhaustResponse'){const params=sequenceParameters(s);body=`<p><b>等待${names[params.player]}回应</b> · 请自行选择${AREAS[params.region].name}一个未横置盟国。回应不消耗本方行动，完成后继续${names[q.owner]}的原行动。</p><label>横置盟国<select id="sequence-exhaust-ally">${readyRegionalAllies(s,params.player,params.region).map(id=>`<option value="${id}">${esc(cards[id]?.name)}</option>`).join('')}</select></label><button id="sequence-resolve">横置所选盟国</button>`;}
 if(step.type==='region')body=`<label>选择地区<select id="sequence-region">${sequenceRegions(s).map(id=>`<option value="${id}">${AREAS[id].name}</option>`).join('')}</select></label><button id="sequence-resolve">确认地区</button>`;
 if(step.type==='foreignInvestment')body=renderForeignInvestmentStep(s,cards);
 if(step.type==='returnArmy'){const params=sequenceParameters(s);body=`<p data-army-owner="">可以支付1外交，把${AREAS[params.region].name}另一位玩家的1军队送回其待命区。</p><label>选择玩家<select id="sequence-other-player">${otherArmyTargets(s,params.region).map(id=>`<option value="${id}">${names[id]} · 当地${s.regions[params.region].armies[id]}军队</option>`).join('')}</select></label><p id="sequence-return-preview" aria-live="polite"></p><button id="sequence-resolve">支付并送回军队</button><button id="sequence-skip">不执行追加效果</button>`;}
 if(step.type==='regions')body=`<p>选择${step.min===step.max?step.min:step.min+'～'+step.max}个不同地区。${esc(step.note||'')}</p><fieldset><legend>所选地区按下方顺序结算</legend>${sequenceRegions(s).map(id=>`<label><input type="checkbox" data-sequence-region="${id}"> ${AREAS[id].name}</label>`).join('')}</fieldset><p id="sequence-regions-preview" aria-live="polite"></p><button id="sequence-resolve">确认所选地区</button>`;
 if(['influence','response'].includes(step.type)){const params=sequenceParameters(s);body=`${step.type==='response'?`<p><b>等待${names[params.player]}回应</b> · 可以接受或拒绝；回应不占用${names[params.player]}的行动，之后继续${names[q.owner]}的行动。</p>`:''}<p>${params.cost?'支付'+amountText(params.cost)+'。':''}${params.gain?'获得'+amountText(params.gain)+'。':''}${params.supplyArmies?'从供应堆放置'+params.supplyArmies+'军队，不扣待命军队。':''}${params.resetBefore?'先重置所选地区一个本方临时影响力，再添加影响力。':''}${params.permanent?'必须放置永久影响力；永久槽满时额外放置，不得1分。':''}</p><label>地区<select id="sequence-region">${sequenceRegions(s).map(id=>`<option value="${id}">${AREAS[id].name}</option>`).join('')||'<option value="">没有可用地区</option>'}</select></label>${params.resetBefore?'<label>先重置的临时影响力<select id="sequence-reset-index"></select></label>':''}<label>添加影响力<select id="sequence-slot"><option value="permanent">永久槽</option>${params.permanent?'':'<option value="temporary">临时槽</option>'}</select></label>${resilienceControls(s,'sequence')}<p id="sequence-influence-preview" aria-live="polite"></p><button id="sequence-resolve">${step.type==='response'?'接受并支付':'支付并完成本段'}</button>${step.type==='response'?'<button id="sequence-decline">拒绝邀请</button>':''}`;}
 if(step.type==='readyAlly')body=`<label>重整盟国<select id="sequence-ally">${p.allies.map(id=>`<option value="${id}">${esc(cards[id]?.name)}${(p.exhaustedAllies||[]).includes(id)?' · 已横置':' · 已就绪'}</option>`).join('')}</select></label><p>可以选择已就绪的盟国，随后继续结算。</p><button id="sequence-resolve">重整并继续</button>`;
 if(step.type==='industrialize')body=`<p>支付10资金提升2种产能，或支付20资金提升3种产能；获得3分，然后继续出牌。产能封顶，提升初级产能不额外发资源。</p><fieldset><legend>选择不同资源</legend>${RESOURCE_LABELS.map((name,k)=>`<label><input type="checkbox" data-sequence-upgrade="${k}"> ${name} ${p.production[k]} → ${Math.min(p.production[k]+1,ECONOMY[s.current].max[k])}</label>`).join('')}</fieldset><p id="sequence-industrial-preview" aria-live="polite"></p><button id="sequence-resolve">支付并提升产能</button>`;
 if(step.type==='fundDiplomacy')body=`<p>可花费至多20资金，每10资金获得3外交，然后介入地区。</p><label>支付金额<select id="sequence-funding">${[0,1,2].map(n=>`<option value="${n}">${n*10}资金 → ${n*3}外交</option>`).join('')}</select></label><p id="sequence-funding-preview" aria-live="polite"></p><button id="sequence-resolve">支付并继续</button>`;
 if(step.type==='searchRegion')body=`<p>可以检索一个地区的全部剩余国家牌，与其中一国改善关系。按通常规则支付费用，随后重洗余牌并揭示两张。</p><label>检索地区<select id="sequence-region">${Object.entries(AREAS).filter(([id])=>regionCountries(s.regions[id]).length).map(([id,a])=>`<option value="${id}">${a.name} · ${regionCountries(s.regions[id]).length}张国家牌</option>`).join('')}</select></label><button id="sequence-resolve">查看所选地区国家牌</button><button id="sequence-skip">不检索，完成本牌</button>`;
 if(step.type==='reset')body=`<label>重置本方临时影响力<select id="sequence-reset">${resetChoices(s).map(x=>`<option value="${x.region}:${x.index}">${AREAS[x.region].name} · 第${x.index+1}个临时位置</option>`).join('')}</select></label><button id="sequence-resolve">重置并继续</button>${step.optional?'<button id="sequence-skip-reset">不重置，继续</button>':''}`;
 if(step.type==='trashToPlay')body=`<p>可以从手牌或弃牌堆移除1张牌，以打出另一张牌。</p><label>要移除的牌<select id="sequence-trash">${['hand','discard'].flatMap(zone=>p[zone].map(id=>`<option value="${zone}:${id}">${zone==='hand'?'手牌':'弃牌'} · ${esc(cards[id]?.name||ACTION_CARDS[id]?.name||'能力牌')}</option>`)).join('')}</select></label><button id="sequence-resolve">移除并获得继续出牌</button><button id="sequence-decline">不移除，完成本牌</button>`;
 if(step.type==='discardToPlay')body=`<p>可以弃置${step.count}张手牌，以打出另一张牌。</p><div class="growth-choice-grid">${p.hand.map(id=>choiceCard(id,cards,false)).join('')}</div><button id="sequence-resolve">弃置所选手牌并继续出牌</button><button id="sequence-decline">不弃牌，完成本牌</button>`;
 if(step.type==='researchPlay')body=`<p>选择费用不超过${step.maxCost}研究力的市场牌，免费取得并立即打出。</p><div class="growth-choice-grid">${sequenceMarket(s).map(id=>choiceCard(id,cards,true)).join('')}</div><button id="sequence-resolve">免费取得所选牌</button>`;
 if(step.type==='upgradeProduce')body=`<p>选择一种资源，提升1产能（已达上限则保持），然后生产该资源。</p><label>资源<select id="sequence-resource">${RESOURCE_LABELS.map((name,k)=>`<option value="${k}">${name} · 产能${p.production[k]} → ${Math.min(p.production[k]+1,ECONOMY[s.current].max[k])}</option>`).join('')}</select></label><label>生产数量<input id="sequence-quantity" type="number" value="1" min="0" max="10"></label><p id="sequence-production-note"></p><button id="sequence-resolve">提升产能、生产并继续</button>`;
 const status=sequenceStatus(s);
 if(status.status==='unavailable'||q.blocked)body=`<p role="status"><b>禁止执行：</b>${esc(q.blocked?.reason||status.reason)}</p>${step.optional?'<button id="sequence-skip">放弃可选效果</button>':''}<p>已保存的前序结果保持不变；本段未扣费或发奖。可撤销上一步，或保留旧存档的手动剩余清单。</p>`;
 const optional=step.optional||['searchRegion','copyAbility','trashToPlay','discardToPlay','response'].includes(step.type);
 return `<section id="sequence-panel"><b>${esc(sequenceName(s))} · 第${q.index+1}/${q.steps.length}步 · ${optional?'可选放弃':'待处理'}</b>${body}${renderSequenceHistory(q)}<details><summary>待处理步骤</summary><ol>${q.steps.slice(q.index).map(x=>`<li>${esc(sequenceStepTitle(x))}${x.optional?'（可选）':''}</li>`).join('')}</ol></details>${q.responder?'':'<details><summary>手动处理选项</summary><p>已结算账目和剩余步骤会保存。只处理剩余效果，不要重付费用或重领收益；转手动后不会自动重跑本牌。</p><button id="sequence-manual">改为手动处理余下效果</button></details>'}</section>`;
}
export function renderSequenceHistory(q){const labels={done:'已结算',declined:'已放弃',unavailable:'无法执行，已略过',legacy:'旧存档记录'};return `<details class="sequence-receipt" ${q.history?.length?'open':''}><summary>已处理步骤与账目</summary><p>以下是已自动记账的实际净变化，包含费用、收益与上限折现；不要重复支付或领取。抽牌只记数量。</p>${q.history?.length?'<ol>'+q.history.map(entry=>`<li><b>${esc(labels[entry.status]||entry.status)} · ${esc(entry.title)}</b>${entry.detail?'<p>'+esc(entry.detail)+'</p>':''}${(entry.changes||[]).map(change=>'<p>'+names[change.player]+'：'+change.items.map(x=>esc(x.label)+(x.delta>0?' +':' ')+x.delta).join('；')+'</p>').join('')}</li>`).join('')+'</ol>':q.index?'<p>旧存档此前步骤已处理，未记录逐项账目；不补扣费用或补发奖励。</p>':'<p>还没有已结算效果；卡牌已打出。</p>'}</details>`;}
export function renderSequenceReport(s){const report=s.flow?.sequenceReports?.[s.current];if(!report)return '';return `<details class="sequence-report" ${report.status==='manual'&&report.round===s.round&&report.turnIndex===s.actionTurns.index?'open':''}><summary>${esc(ACTION_CARDS[report.cardId]?.name||'卡牌')} · ${report.status==='manual'?'手动剩余步骤':'最近结算记录'}（第${report.round}轮）</summary>${renderSequenceHistory(report)}${report.status==='manual'?`<p><b>以下效果尚未自动结算：</b>${esc(report.reason)}</p><ol>${report.remaining.map(x=>'<li>'+esc(x.title)+(x.detail?' · '+esc(x.detail):'')+'</li>').join('')}</ol><p>按牌面完成手动剩余效果后结束行动。此清单不会再次自动发奖。</p>`:'<p>本牌序列已结束；可执行效果已经处理。</p>'}</details>`;}
function choiceCard(id,cards,radio){return `<label class="growth-choice"><img src="${esc(cards[id]?.image)}" alt="${esc(cards[id]?.name||'能力牌')}"><span><input type="${radio?'radio':'checkbox'}" name="sequence-card" data-sequence-card="${id}"> ${esc(cards[id]?.name||ACTION_CARDS[id]?.name||'能力牌')}</span></label>`;}
function amountText(value){return [...(value.money?[value.money+'资金']:[]),...(value.vp?[value.vp+'分']:[]),...Object.entries(value.resources||{}).map(([k,n])=>n+RESOURCE_LABELS[k])].join('、')||'0';}
export function readSequenceForm(s){const step=sequenceStep(s),a={type:'resolveSequenceStep'};if(step.type==='chooseActions')a.choices=[...document.querySelectorAll('[data-sequence-choice]')].map(el=>el.value);
 if(['region','searchRegion','influence','response'].includes(step.type))a.region=document.querySelector('#sequence-region')?.value;
 if(step.type==='regions')a.regions=[...document.querySelectorAll('[data-sequence-region]:checked')].map(el=>el.dataset.sequenceRegion);
 if(step.type==='returnArmy')a.targetPlayer=document.querySelector('#sequence-other-player')?.value;
 if(step.type==='foreignInvestment')Object.assign(a,readForeignInvestment());
 if(step.type==='inspectOpponent')a.targetPlayer=document.querySelector('#sequence-spy-player')?.value;
 if(['aidAllies','swapInfluence','beijingConsensus','regimeChange'].includes(step.type))Object.assign(a,readDDAssetStep(step));
 if(step.type==='copyAbility')Object.assign(a,readCopyAbility());
 if(step.type==='exhaustResponse')a.country=document.querySelector('#sequence-exhaust-ally')?.value;
 if(step.type==='response')a.accept=true;
 if(['influence','response'].includes(step.type))Object.assign(a,{slot:document.querySelector('#sequence-slot')?.value,resetIndex:Number(document.querySelector('#sequence-reset-index')?.value??NaN),resilience:readResilience('sequence')});
 if(step.type==='readyAlly')a.country=document.querySelector('#sequence-ally')?.value;
 if(step.type==='industrialize')a.upgrades=[...document.querySelectorAll('[data-sequence-upgrade]:checked')].map(el=>Number(el.dataset.sequenceUpgrade));
 if(step.type==='fundDiplomacy')a.bundles=Number(document.querySelector('#sequence-funding')?.value);
 if(step.type==='reset'){const [region,index]=(document.querySelector('#sequence-reset')?.value||'').split(':');Object.assign(a,{region,index:Number(index)});}
 if(step.type==='trashToPlay'){const [zone,targetCard]=(document.querySelector('#sequence-trash')?.value||'').split(':');Object.assign(a,{accept:true,zone,targetCard});}
 if(step.type==='discardToPlay')Object.assign(a,{accept:true,cards:[...document.querySelectorAll('[data-sequence-card]:checked')].map(el=>el.dataset.sequenceCard)});
 if(step.type==='researchPlay')a.targetCard=document.querySelector('[data-sequence-card]:checked')?.dataset.sequenceCard;
 if(step.type==='upgradeProduce')Object.assign(a,{key:Number(document.querySelector('#sequence-resource')?.value),quantity:Number(document.querySelector('#sequence-quantity')?.value)});return a;
}
export function updateSequencePanel(s){
 if(s.flow?.pendingGrowth)return;
 if(s.flow?.cardResolution&&(s.flow.cardResolution.responder||s.flow.cardResolution.owner)!==s.current)return;
 if(s.flow?.cardResolution&&sequenceStatus(s).status==='unavailable')return;
 if(s.flow?.cardResolution&&updateDDAssetStep(s,sequenceParameters(s)))return;
 if(updateForeignInvestment(s))return;
 if(document.querySelector('#sequence-copy-preview')){updateCopyAbility(s,sequenceParameters(s));return;}
 if(document.querySelector('#sequence-return-preview')){try{const result=returnArmyPreview(s,readSequenceForm(s),sequenceParameters(s));document.querySelector('#sequence-return-preview').dataset.armyOwner=result.player;document.querySelector('#sequence-resolve').dataset.armyOwner=result.player;document.querySelector('#sequence-return-preview').textContent=`${names[result.player]}的军队返回其待命区，不移出游戏。`;document.querySelector('#sequence-resolve').disabled=false;}catch(error){document.querySelector('#sequence-return-preview').textContent=error.message;document.querySelector('#sequence-resolve').disabled=true;}return;}
 if(document.querySelector('#sequence-regions-preview')){const step=sequenceStep(s),n=readSequenceForm(s).regions.length,valid=n>=step.min&&n<=step.max;document.querySelector('#sequence-regions-preview').textContent=valid?'已选'+n+'个地区。':'请选择规定数量的地区。';document.querySelector('#sequence-resolve').disabled=!valid;return;}
 if(document.querySelector('#sequence-industrial-preview')){const button=document.querySelector('#sequence-resolve');try{const r=industrializePreview(s,readSequenceForm(s));document.querySelector('#sequence-industrial-preview').textContent=`支付${r.cost}资金，获得3分，随后打出另一张牌。`;button.disabled=false;}catch(error){document.querySelector('#sequence-industrial-preview').textContent=error.message;button.disabled=true;}return;}
 if(document.querySelector('#sequence-funding-preview')){const n=Number(document.querySelector('#sequence-funding').value),p=s.players[s.current],enough=p.money>=n*10;document.querySelector('#sequence-funding-preview').textContent=enough?`支付${n*10}资金，实际增加${Math.min(10,p.resources[5]+n*3)-p.resources[5]}外交。`: '资金不足';document.querySelector('#sequence-resolve').disabled=!enough;return;}
 if(document.querySelector('#sequence-influence-preview')){const region=document.querySelector('#sequence-region').value,reset=document.querySelector('#sequence-reset-index');if(reset){const previous=reset.value;reset.innerHTML=(s.regions[region]?.temporary||[]).map((owner,i)=>owner===s.current?`<option value="${i}">第${i+1}个临时位置</option>`:'').join('');if([...reset.options].some(o=>o.value===previous))reset.value=previous;}
  const params=sequenceParameters(s),projection=structuredClone(s);if(params.resetBefore&&reset?.value!==undefined&&reset.value!==''){const temporary=projection.regions[region]?.temporary;if(temporary){temporary.splice(Number(reset.value),1);temporary.push(s.current);}}
  updateResilience(projection,region,document.querySelector('#sequence-slot').value,'sequence');const button=document.querySelector('#sequence-resolve');try{const result=sequenceInfluencePreview(s,readSequenceForm(s));document.querySelector('#sequence-influence-preview').textContent=`在${AREAS[result.region].name}添加影响力，获得${result.vp}分。`;button.disabled=false;}catch(error){document.querySelector('#sequence-influence-preview').textContent=error.message;button.disabled=true;}return;
 }
 const el=document.querySelector('#sequence-resource');if(!el)return;const k=Number(el.value),p=s.players[s.current],max=Math.min(p.production[k]+1,ECONOMY[s.current].max[k]),input=document.querySelector('#sequence-quantity');input.disabled=k<3;input.max=max;if(k<3)input.value=max;document.querySelector('#sequence-production-note').textContent=k<3?'初级资源按提升后的完整产能生产；超出库存上限自动折现。':k===5?'每点外交支付3资金。':`每份消耗1${RESOURCE_LABELS[k===6?1:0]}和1${RESOURCE_LABELS[k===3?1:2]}。`;}
